.nav { background: #0b6fd6; color: white; padding: 12px; }

.card {
  position: relative;      /* làm "mốc" cho phần tử absolute bên trong */
  width: 240px;
  margin: 24px;
  padding: 16px;
  border: 1px solid #ccc;
}

.badge {
  position: absolute;      /* thoát khỏi luồng, định vị theo .card */
  top: 8px;
  right: 8px;
  background: tomato;
  color: white;
  padding: 2px 8px;
  border-radius: 99px;
}

