solution.code:
.card {
  position: relative;
  width: 240px;
  margin: 24px;
  padding: 16px;
  border: 1px solid #ccc;
}

.badge {
  position: absolute;
  top: 0;
  right: 0;
  background: tomato;
  color: white;
  padding: 2px 8px;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 10;
  background: #0b6fd6;
  color: white;
  padding: 12px;
}
